BEGIN TRANSACTION;
CREATE TABLE  "coaches" ("coachID"	INTEGER,"firstname"	varchar(100),"lastname"	varchar(100), PRIMARY KEY("coachID"));
CREATE TABLE  "division" ("divName"	varchar(50), "conference"	varchar(100) NOT NULL, PRIMARY KEY("divName"));
CREATE TABLE  "locations" ("locationID"	INTEGER,"country"	varchar(100) NOT NULL,"city"	varchar(100) NOT NULL,PRIMARY KEY("locationID"));
CREATE TABLE  "officials" ("officialID"	INTEGER,"firstname"	varchar(100),"lastname"	varchar(100),"jersey"	INTEGER,PRIMARY KEY("officialID"));
CREATE TABLE  "stadiums" ("stadiumName"	varchar(100),"capacity"	INTEGER NOT NULL,"locationID"	INTEGER,PRIMARY KEY("stadiumName"),FOREIGN KEY("locationID") REFERENCES "locations"("locationID"));
CREATE TABLE  "teams" ("teamName" varchar(100),"basedIn"	varchar(100) NOT NULL,"yearfounded"	INTEGER NOT NULL,"divName"	varchar(50),"stadiumName"	varchar(100),PRIMARY KEY("teamName"),FOREIGN KEY("divName") REFERENCES "division"("divName"),FOREIGN KEY("stadiumName") REFERENCES "stadiums"("stadiumName"));
CREATE TABLE  "seasons" ("years" varchar(50),"champion"	varchar(100) NOT NULL,PRIMARY KEY("years"),FOREIGN KEY("champion") REFERENCES "teams"("teamName"));
CREATE TABLE  "games" ("gameID"	INTEGER,"date"	varchar(100) NOT NULL,"season"	varchar(50) NOT NULL,"stadiumName"	varchar(100) NOT NULL,PRIMARY KEY("gameID"),FOREIGN KEY("season") REFERENCES "seasons"("years"),FOREIGN KEY("stadiumName") REFERENCES "stadiums"("stadiumName"));
CREATE TABLE  "gameTeamStats" ("teamName"	varchar(100),"gameID"	INTEGER,"min"	INTEGER,"pts"	INTEGER,"fgm"	INTEGER,"fga"	INTEGER,"fg%"	REAL,"3pm"	INTEGER,"3pa"	INTEGER,"3p%"	REAL,"ftm"	INTEGER,"fta"	INTEGER,"ft%"	REAL,"oreb"	INTEGER,"dreb"	INTEGER,"reb"	INTEGER,"ast"	INTEGER,"tov"	INTEGER,"stl"	INTEGER,"blk"	INTEGER,"pf"	INTEGER,"+/-"	INTEGER,PRIMARY KEY("teamName",   "gameID"),FOREIGN KEY("gameID") REFERENCES "games"("gameID"),FOREIGN KEY("teamName") REFERENCES "teams"("teamName"));
CREATE TABLE  "gameTeamInfo" ("gameID"	INTEGER,"homeTeam"	varchar(100) NOT NULL,"awayTeam"	varchar(100) NOT NULL,"winner"	varchar(100),PRIMARY KEY("gameID"),FOREIGN KEY("awayTeam") REFERENCES "teams"("teamName"),FOREIGN KEY("gameID") REFERENCES "games"("gameID"),FOREIGN KEY("homeTeam") REFERENCES "teams"("teamName"),FOREIGN KEY("winner") REFERENCES "teams"("teamName"));
CREATE TABLE  "players" ("playerID"	INTEGER,"firstname"	varchar(100),"lastname"	varchar(100),"birthdate"	varchar(100) NOT NULL,"height"	varchar(100) NOT NULL,"weight"	INTEGER NOT NULL,"position"	varchar(100) NOT NULL,"locationID"	INTEGER,PRIMARY KEY("playerID"),FOREIGN KEY("locationID") REFERENCES "locations"("locationID"));
CREATE TABLE  "gamePlayerStats" ("playerID"	INTEGER,"gameID"	INTEGER,"min"	INTEGER,"pts"	INTEGER,"fgm"	INTEGER,"fga"	INTEGER,"fg%"	REAL,"3pm"	INTEGER,"3pa"	INTEGER,"3p%"	REAL,"ftm"	INTEGER,"fta"	INTEGER,"ft%"	REAL,"oreb"	INTEGER,"dreb"	INTEGER, "reb" INTEGER, "ast"	INTEGER,"stl"	INTEGER,"blk"	INTEGER,"tov"	INTEGER,"pf"	INTEGER,"+/-"	INTEGER,PRIMARY KEY("playerID",   "gameID"),FOREIGN KEY("gameID") REFERENCES "games"("gameID"),FOREIGN KEY("playerID") REFERENCES "players"("playerID"));
CREATE TABLE  "manage" ("coachID"	INTEGER,"teamName"	varchar(100),"season"	varchar(50),PRIMARY KEY("coachID",   "teamName",   "season"),FOREIGN KEY("coachID") REFERENCES "coaches"("coachID"),FOREIGN KEY("season") REFERENCES "seasons"("years"),FOREIGN KEY("teamName") REFERENCES "teams"("teamName"));
CREATE TABLE  "officiate" ("gameID"	INTEGER,"officialID"	INTEGER,PRIMARY KEY("gameID",   "officialID"),FOREIGN KEY("gameID") REFERENCES "games"("gameID"),FOREIGN KEY("officialID") REFERENCES "officials"("officialID"));
CREATE TABLE  "play" ("season"	varchar(50),"playerID"	INTEGER,"teamName"	varchar(100),"jersey"	INTEGER NOT NULL,PRIMARY KEY("season",   "playerID"),FOREIGN KEY("playerID") REFERENCES "players"("playerID"),FOREIGN KEY("season") REFERENCES "seasons"("years"),FOREIGN KEY("teamName") REFERENCES "teams"("teamName"));
CREATE TABLE  "draftInfo" ("draftYear"	INTEGER,"round"	INTEGER,"pick"	INTEGER,"playerID"	INTEGER,"teamDrafted"	varchar(100),PRIMARY KEY("draftYear",   "round",   "pick"),FOREIGN KEY("playerID") REFERENCES "players"("playerID"),FOREIGN KEY("teamDrafted") REFERENCES "teams"("teamName"));
CREATE TABLE  "playoffGames" ("gameID"	INTEGER,"round"	varchar(100) NOT NULL,PRIMARY KEY("gameID"),FOREIGN KEY("gameID") REFERENCES "games"("gameID"));
CREATE TABLE  "teach" ("coachID"	INTEGER,"playerID"	INTEGER,PRIMARY KEY("coachID",   "playerID"),FOREIGN KEY("coachID") REFERENCES "coaches"("coachID"),FOREIGN KEY("playerID") REFERENCES "players"("playerID"));
COMMIT;